// src/utils/dmSansFont.js
//
// DM Sans, embedded so the printed scheduling sheet uses the same typeface as
// the app itself rather than a jsPDF built-in. Four faces are carried because
// the sheet's hierarchy needs four: regular for data, medium for row labels,
// bold for post names and the day title, italic for placeholders and captions.
//
// FONT LICENCE — DM Sans is licensed under the SIL Open Font License v1.1.
// Copyright 2014 The DM Sans Project Authors
// (https://github.com/googlefonts/dm-fonts). The full licence text ships
// alongside this file as ./OFL.txt and MUST be kept with it; the OFL requires
// the copyright and licence notice to travel with the font data.
//
// This module is imported ONLY by schedulingSheetPdf.js, which the scheduling
// page loads through a dynamic import(). That keeps roughly 255KB of base64
// out of the main bundle — it is downloaded only by someone who actually
// prints a sheet.

/** The four faces, base64-encoded TTF, ready for jsPDF's virtual file system. */
const DM_SANS_FACES = [
  {
    style: 'normal',
    vfs: 'DMSans-normal.ttf',
    data:
      '',
  },
  {
    style: 'medium',
    vfs: 'DMSans-medium.ttf',
    data:
      '',
  },
  {
    style: 'bold',
    vfs: 'DMSans-bold.ttf',
    data:
      '',
  },
  {
    style: 'italic',
    vfs: 'DMSans-italic.ttf',
    data:
      '',
  },
];

/**
 * Register every DM Sans face on a jsPDF document.
 *
 * Must be called before any text is measured or drawn: jsPDF resolves a font
 * by name at draw time, and an unregistered name silently falls back to
 * Helvetica — which would measure differently and quietly break the column
 * widths this layout computes.
 */
export function registerDmSans(doc) {
  for (const face of DM_SANS_FACES) {
    doc.addFileToVFS(face.vfs, face.data);
    doc.addFont(face.vfs, 'DMSans', face.style);
  }
}

export default registerDmSans;
